import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts - I knew we'd need these
const mockCartContext = {
  items: [{ id: '1', name: 'Widget', price: 29.99 }],
  total: 29.99,
  clearCart: vi.fn(),
};

const mockPaymentContext = {
  processPayment: vi.fn(),
};

vi.mock('./CartContext', () => ({
  useCart: () => mockCartContext,
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => mockPaymentContext,
}));

describe('Checkout Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockCartContext.items = [{ id: '1', name: 'Widget', price: 29.99 }];
  });

  describe('Happy Path - Complete Checkout Flow', () => {
    it('completes full checkout from shipping to confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      mockPaymentContext.processPayment.mockResolvedValue({ orderId: 'ORD-123' });

      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Main St');
      await user.type(screen.getByLabelText(/city/i), 'Springfield');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'John Doe');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/widget/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText('ORD-123')).toBeInTheDocument();
      expect(onComplete).toHaveBeenCalledWith('ORD-123');
    });
  });

  describe('Form Validation', () => {
    it('displays street address error when empty', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });

    it('validates card number requires 16 digits', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      // Navigate to payment step first
      await fillShippingForm(user);

      await user.type(screen.getByLabelText(/card number/i), '1234');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      expect(screen.getByText(/valid 16-digit card number required/i)).toBeInTheDocument();
    });
  });

  describe('Error States and Recovery', () => {
    it('displays payment error and allows retry', async () => {
      const user = userEvent.setup();
      mockPaymentContext.processPayment.mockRejectedValueOnce(new Error('Card declined'));

      render(<Checkout />);
      await completeToReviewStep(user);

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByText(/card declined/i)).toBeInTheDocument();
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  describe('Loading States', () => {
    it('disables buttons during payment processing', async () => {
      const user = userEvent.setup();
      mockPaymentContext.processPayment.mockImplementation(
        () => new Promise(() => {}) // Never resolves
      );

      render(<Checkout />);
      await completeToReviewStep(user);

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
    });
  });

  describe('Edge Cases', () => {
    it('shows empty cart message when no items', () => {
      mockCartContext.items = [];
      render(<Checkout onCancel={vi.fn()} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/your cart is empty/i);
    });
  });

  describe('Accessibility', () => {
    it('has no accessibility violations on shipping step', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });

    it('progress indicator shows current step', () => {
      render(<Checkout />);
      const nav = screen.getByRole('navigation', { name: /checkout progress/i });
      expect(within(nav).getByText('Shipping')).toHaveAttribute('aria-current', 'step');
    });
  });
});

// Helpers - I knew we'd need these too
async function fillShippingForm(user) {
  await user.type(screen.getByLabelText(/street/i), '123 Main');
  await user.type(screen.getByLabelText(/city/i), 'LA');
  await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
  await user.type(screen.getByLabelText(/zip/i), '90210');
  await user.click(screen.getByRole('button', { name: /continue to payment/i }));
}

async function completeToReviewStep(user) {
  await fillShippingForm(user);
  await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
  await user.type(screen.getByLabelText(/expiry/i), '12/25');
  await user.type(screen.getByLabelText(/cvv/i), '123');
  await user.type(screen.getByLabelText(/name on card/i), 'John');
  await user.click(screen.getByRole('button', { name: /review order/i }));
}
